/* Linux interoperability fixture. Both protocol headers are generated by wayland-scanner. */
#define _GNU_SOURCE
#include "wayland-client-protocol.h"
#include "xdg-shell-client-protocol.h"
#include <xkbcommon/xkbcommon.h>
#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <sys/stat.h>
#include <sys/un.h>
#include <unistd.h>

enum { WIDTH = 20, HEIGHT = 16, STRIDE = 96, OFFSET = 64, POOL_SIZE = 4096 };

struct client {
    struct wl_display *display;
    struct wl_compositor *compositor;
    struct wl_shm *shm;
    struct wl_seat *seat;
    struct wl_keyboard *keyboard;
    struct wl_output *output;
    struct xdg_wm_base *shell;
    bool test_output;
    unsigned output_stage, enters, leaves;
    bool xrgb, argb, keymap, top_configured, configured, frame, released;
    uint32_t serial;
};

static void require(bool ok, const char *message)
{
    if (!ok) {
        fprintf(stderr, "reference-client: %s\n", message);
        exit(EXIT_FAILURE);
    }
}

/* Unused arguments in these listeners are part of the upstream callback ABI. */
static void keymap(void *data, struct wl_keyboard *keyboard, uint32_t format, int fd, uint32_t size)
{
    struct client *c = data;
    struct stat st;
    require(format == WL_KEYBOARD_KEYMAP_FORMAT_XKB_V1 && size && size <= 1024 * 1024,
            "invalid XKB keymap format or size");
    require(fstat(fd, &st) == 0 && st.st_size >= size, "invalid XKB backing");
    const char *text = mmap(NULL, size, PROT_READ, MAP_PRIVATE, fd, 0);
    close(fd);
    require(text != MAP_FAILED && text[size - 1] == 0, "unreadable XKB keymap");
    struct xkb_context *context = xkb_context_new(XKB_CONTEXT_NO_DEFAULT_INCLUDES);
    require(context != NULL, "xkb_context_new");
    struct xkb_keymap *map = xkb_keymap_new_from_string(context, text,
            XKB_KEYMAP_FORMAT_TEXT_V1, XKB_KEYMAP_COMPILE_NO_FLAGS);
    require(map != NULL, "libxkbcommon rejected keymap");
    xkb_keymap_unref(map);
    xkb_context_unref(context);
    munmap((void *)text, size);
    c->keymap = true;
}

static void enter(void *d, struct wl_keyboard *k, uint32_t serial, struct wl_surface *s, struct wl_array *keys) {}
static void leave(void *d, struct wl_keyboard *k, uint32_t serial, struct wl_surface *s) {}
static void key(void *d, struct wl_keyboard *k, uint32_t serial, uint32_t time, uint32_t code, uint32_t state) {}
static void modifiers(void *d, struct wl_keyboard *k, uint32_t serial, uint32_t a, uint32_t b, uint32_t c, uint32_t group) {}
static void repeat(void *d, struct wl_keyboard *k, int32_t rate, int32_t delay) {}
static const struct wl_keyboard_listener keys = {keymap, enter, leave, key, modifiers, repeat};

static void capabilities(void *data, struct wl_seat *seat, uint32_t caps)
{
    struct client *c = data;
    if ((caps & WL_SEAT_CAPABILITY_KEYBOARD) && !c->keyboard) {
        c->keyboard = wl_seat_get_keyboard(seat);
        require(c->keyboard && wl_keyboard_add_listener(c->keyboard, &keys, c) == 0, "get keyboard");
    }
}

static void seat_name(void *d, struct wl_seat *seat, const char *name) {}
static const struct wl_seat_listener seat_events = {capabilities, seat_name};

static void format(void *data, struct wl_shm *shm, uint32_t value)
{
    struct client *c = data;
    c->xrgb |= value == WL_SHM_FORMAT_XRGB8888;
    c->argb |= value == WL_SHM_FORMAT_ARGB8888;
}
static const struct wl_shm_listener shm_events = {format};

static void ping(void *d, struct xdg_wm_base *shell, uint32_t serial)
{
    xdg_wm_base_pong(shell, serial);
}
static const struct xdg_wm_base_listener shell_events = {ping};

static void output_geometry(void *data, struct wl_output *output, int32_t x, int32_t y,
        int32_t width_mm, int32_t height_mm, int32_t subpixel, const char *make, const char *model,
        int32_t transform)
{
    struct client *c = data;
    require(c->output == output && c->output_stage == 0 && x == 0 && y == 0 &&
            width_mm == 0 && height_mm == 0 && subpixel == WL_OUTPUT_SUBPIXEL_UNKNOWN &&
            !strcmp(make, "JNOX") && !strcmp(model, "RAM framebuffer") &&
            transform == WL_OUTPUT_TRANSFORM_NORMAL, "wl_output.geometry");
    c->output_stage++;
}

static void output_mode(void *data, struct wl_output *o, uint32_t flags, int32_t w, int32_t h, int32_t hz)
{
    struct client *c = data;
    require(c->output_stage == 1 && flags == (WL_OUTPUT_MODE_CURRENT | WL_OUTPUT_MODE_PREFERRED) &&
            w == 320 && h == 240 && hz == 0, "wl_output.mode");
    c->output_stage++;
}

static void output_scale(void *data, struct wl_output *o, int32_t scale)
{
    struct client *c = data;
    require(c->output_stage == 2 && scale == 1, "wl_output.scale");
    c->output_stage++;
}

static void output_done(void *data, struct wl_output *o)
{
    struct client *c = data;
    require(c->output_stage == 3, "wl_output.done");
    c->output_stage++;
}
static const struct wl_output_listener output_events = {
    .geometry = output_geometry, .mode = output_mode, .scale = output_scale, .done = output_done,
};

static void surface_enter(void *data, struct wl_surface *s, struct wl_output *output)
{
    struct client *c = data;
    require(c->output_stage == 4 && c->output == output && !c->enters, "wl_surface.enter");
    ++c->enters;
}
static void surface_leave(void *data, struct wl_surface *s, struct wl_output *output)
{
    struct client *c = data;
    require(c->output == output && c->enters == 1 && !c->leaves, "wl_surface.leave");
    ++c->leaves;
}
static const struct wl_surface_listener output_membership = {.enter = surface_enter, .leave = surface_leave};

static void global(void *data, struct wl_registry *r, uint32_t id, const char *name, uint32_t version)
{
    struct client *c = data;
    if (!strcmp(name, wl_compositor_interface.name) && version >= 4) {
        c->compositor = wl_registry_bind(r, id, &wl_compositor_interface, 4);
    } else if (!strcmp(name, wl_shm_interface.name) && version >= 1) {
        c->shm = wl_registry_bind(r, id, &wl_shm_interface, 1);
        require(c->shm && wl_shm_add_listener(c->shm, &shm_events, c) == 0, "bind shm");
    } else if (!strcmp(name, xdg_wm_base_interface.name) && version >= 1) {
        c->shell = wl_registry_bind(r, id, &xdg_wm_base_interface, 1);
        require(c->shell && xdg_wm_base_add_listener(c->shell, &shell_events, c) == 0, "bind xdg");
    } else if (!strcmp(name, wl_seat_interface.name) && version >= 4) {
        c->seat = wl_registry_bind(r, id, &wl_seat_interface, 4);
        require(c->seat && wl_seat_add_listener(c->seat, &seat_events, c) == 0, "bind seat");
    } else if (c->test_output && !strcmp(name, wl_output_interface.name) && version >= 2) {
        require(!c->output, "duplicate output global");
        c->output = wl_registry_bind(r, id, &wl_output_interface, 2);
        require(c->output && wl_output_add_listener(c->output, &output_events, c) == 0, "bind wl_output v2");
    }
}
static void removed(void *d, struct wl_registry *r, uint32_t id) {}
static const struct wl_registry_listener registry_events = {global, removed};

static void toplevel_configure(void *data, struct xdg_toplevel *top, int32_t w, int32_t h, struct wl_array *states)
{
    ((struct client *)data)->top_configured = true;
}
static void toplevel_close(void *d, struct xdg_toplevel *top) { require(false, "unexpected close"); }
static const struct xdg_toplevel_listener top_events = {.configure = toplevel_configure, .close = toplevel_close};

static void configure(void *data, struct xdg_surface *surface, uint32_t serial)
{
    struct client *c = data;
    require(c->top_configured, "xdg_surface.configure preceded initial toplevel configure");
    xdg_surface_ack_configure(surface, serial);
    c->configured = true;
    c->serial = serial;
}
static const struct xdg_surface_listener surface_events = {configure};

static void frame(void *data, struct wl_callback *callback, uint32_t time)
{
    ((struct client *)data)->frame = true;
    wl_callback_destroy(callback);
}
static const struct wl_callback_listener frame_events = {frame};

static void release(void *data, struct wl_buffer *buffer) { ((struct client *)data)->released = true; }
static const struct wl_buffer_listener buffer_events = {release};

static struct wl_buffer *make_buffer(struct client *c)
{
    int fd = memfd_create("jnox-reference-shm", MFD_CLOEXEC);
    require(fd >= 0 && ftruncate(fd, POOL_SIZE) == 0, "create pixel backing");
    unsigned char *pixels = mmap(NULL, POOL_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    require(pixels != MAP_FAILED, "map pixel backing");
    memset(pixels, 0xd7, POOL_SIZE);
    for (unsigned y = 0; y < HEIGHT; y++) {
        uint32_t *row = (uint32_t *)(pixels + OFFSET + y * STRIDE);
        for (unsigned x = 0; x < WIDTH; x++)
            row[x] = 0x005100a3 + (x << 8) + (y << 16);
    }
    munmap(pixels, POOL_SIZE);
    char procpath[64];
    snprintf(procpath, sizeof procpath, "/proc/self/fd/%d", fd);
    int readonly = open(procpath, O_RDONLY | O_CLOEXEC);
    require(readonly >= 0, "derive read-only FD");
    close(fd);
    struct wl_shm_pool *pool = wl_shm_create_pool(c->shm, readonly, POOL_SIZE);
    close(readonly);
    require(pool != NULL, "create shm pool");
    struct wl_buffer *buffer = wl_shm_pool_create_buffer(pool, OFFSET, WIDTH, HEIGHT, STRIDE, WL_SHM_FORMAT_XRGB8888);
    require(buffer && wl_buffer_add_listener(buffer, &buffer_events, c) == 0, "create buffer");
    wl_shm_pool_destroy(pool);
    return buffer;
}

static int endpoint(const char *option, const char *value)
{
    if (!strcmp(option, "--fd")) {
        char *end;
        errno = 0;
        long fd = strtol(value, &end, 10);
        require(!errno && *value && !*end && fd >= 0 && fd <= INT_MAX, "invalid fd");
        return (int)fd;
    }
    struct sockaddr_un addr = {.sun_family = AF_UNIX};
    require(!strcmp(option, "--socket") && value[0] == '/' && strlen(value) < sizeof addr.sun_path,
            "expected an absolute UNIX socket pathname");
    strcpy(addr.sun_path, value);
    int fd = socket(AF_UNIX, SOCK_STREAM | SOCK_CLOEXEC, 0);
    require(fd >= 0 && connect(fd, (struct sockaddr *)&addr, sizeof addr) == 0, "connect UNIX socket");
    return fd;
}

int main(int argc, char **argv)
{
    bool hold = false, geometry = false, output = false;
    require(argc >= 3, "missing endpoint");
    for (int i = 3; i < argc; i++) {
        if (!strcmp(argv[i], "--hold-frame") && !hold) hold = true;
        else if (!strcmp(argv[i], "--geometry") && !geometry) geometry = true;
        else if (!strcmp(argv[i], "--output") && !output) output = true;
        else require(false, "unexpected reference-client argument");
    }
    alarm(30);
    struct client c = {.test_output = output};
    c.display = wl_display_connect_to_fd(endpoint(argv[1], argv[2]));
    require(c.display != NULL, "connect libwayland-client");
    struct wl_registry *registry = wl_display_get_registry(c.display);
    require(registry && wl_registry_add_listener(registry, &registry_events, &c) == 0, "get registry");
    require(wl_display_roundtrip(c.display) >= 0 && c.compositor && c.shm && c.shell && c.seat,
            "missing required registry globals");
    require(!output || c.output, "missing wl_output v2");
    while (!c.keymap || !c.argb || !c.xrgb || (output && c.output_stage < 4))
        require(wl_display_dispatch(c.display) >= 0, "receive shm formats and XKB keymap");

    struct wl_surface *surface = wl_compositor_create_surface(c.compositor);
    require(surface != NULL, "create surface");
    if (output) require(wl_surface_add_listener(surface, &output_membership, &c) == 0, "surface listener");
    struct xdg_surface *xdg = xdg_wm_base_get_xdg_surface(c.shell, surface);
    require(xdg && xdg_surface_add_listener(xdg, &surface_events, &c) == 0, "get xdg surface");
    struct xdg_toplevel *top = xdg_surface_get_toplevel(xdg);
    require(top && xdg_toplevel_add_listener(top, &top_events, &c) == 0, "get toplevel");
    if (output) xdg_toplevel_set_fullscreen(top, c.output);
    wl_surface_commit(surface);
    while (!c.configured)
        require(wl_display_dispatch(c.display) >= 0, "receive initial configure");

    struct wl_buffer *buffer = make_buffer(&c);
    if (geometry) xdg_surface_set_window_geometry(xdg, 3, 2, 14, 12);
    wl_surface_attach(surface, buffer, 0, 0);
    wl_surface_damage(surface, 0, 0, WIDTH, HEIGHT);
    struct wl_callback *cb = wl_surface_frame(surface);
    require(cb && wl_callback_add_listener(cb, &frame_events, &c) == 0, "request frame");
    wl_surface_commit(surface);
    while (!c.frame)
        require(wl_display_dispatch(c.display) >= 0, "receive frame callback");
    if (hold) {
        puts("FRAME");
        fflush(stdout);
        require(getchar() == '\n', "frame capture handshake");
    }
    if (output) {
        require(c.enters == 1 && !c.leaves, "mapped output membership");
        wl_surface_attach(surface, NULL, 0, 0);
        wl_surface_commit(surface);
        require(wl_display_roundtrip(c.display) >= 0 && c.leaves == 1, "unmapped output membership");
        wl_output_destroy(c.output); /* Local v2 proxy destructor. */
    }
    xdg_toplevel_destroy(top);
    xdg_surface_destroy(xdg);
    wl_surface_destroy(surface);
    while (!c.released)
        require(wl_display_dispatch(c.display) >= 0, "receive buffer release");

    wl_buffer_destroy(buffer);
    wl_keyboard_release(c.keyboard);
    wl_seat_destroy(c.seat); /* wl_seat.release was introduced in version 5. */
    xdg_wm_base_destroy(c.shell);
    wl_shm_destroy(c.shm);
    wl_compositor_destroy(c.compositor);
    wl_registry_destroy(registry);
    require(wl_display_roundtrip(c.display) >= 0, "final roundtrip");
    wl_display_disconnect(c.display);
    printf("PASS configure_serial=%u frame=1 buffer_release=1 xkb_keymap=1\n", c.serial);
    return 0;
}
